precision highp float;
uniform float amount; // 0 2 1
void mainImage(out vec4 fragColor, in vec2 fragCoord){
 vec2 uv = fragCoord/iResolution.xy;
 float b = texture(iChannel0, uv).r;
 vec3 t = texture2D(iChannel1, uv*2.0).rgb;
 float a = texture(iChannel2, vec2(0.1,0.25)).x;
 fragColor = vec4(b*amount, t.r*0.5, a, 0.3);
}
